   224  /*
   225   * Append a string printf()-style
   226   */
   227  CURLcode curlx_dyn_addf(struct dynbuf *s, const char *fmt, ...)
   228  {
   229    CURLcode result;
   230    va_list ap;
   231    DEBUGASSERT(s);
   232    DEBUGASSERT(s->init == DYNINIT);
   233    DEBUGASSERT(!s->leng || s->bufr);
   234    va_start(ap, fmt);
   235    result = curlx_dyn_vaddf(s, fmt, ap);
   236    va_end(ap);
   237    return result;
   238  }
