   251  char *curlx_dyn_take(struct dynbuf *s, size_t *plen)
   252  {
   253    char *ptr = s->bufr;
   254    DEBUGASSERT(s);
   255    DEBUGASSERT(s->init == DYNINIT);
   256    *plen = s->leng;
   257    s->bufr = NULL;
   258    s->leng = 0;
   259    s->allc = 0;
   260    return ptr;
   261  }
