   285  /*
   286   * Set a new (smaller) length.
   287   */
   288  CURLcode curlx_dyn_setlen(struct dynbuf *s, size_t set)
   289  {
   290    DEBUGASSERT(s);
   291    DEBUGASSERT(s->init == DYNINIT);
   292    DEBUGASSERT(!s->leng || s->bufr);
   293    if(set > s->leng)
   294      return CURLE_BAD_FUNCTION_ARGUMENT;
   295    s->leng = set;
   296    s->bufr[s->leng] = 0;
   297    return CURLE_OK;
   298  }
